package com.daniil.wristlens.wear;
import android.app.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;
import com.daniil.wristlens.shared.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.util.ReflectionHelpers;
import java.util.*;import java.util.concurrent.atomic.AtomicReference;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="en-rUS-w240dp-h240dp-round-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class MenuInputTest {
 Activity activity;
 @Before public void before(){activity=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(activity);}
 @After public void after(){for(Dialog d:new ArrayList<>(ShadowDialog.getShownDialogs()))d.dismiss();activity.finish();}
 static JSONObject state(){return Wire.object("phase","ready","camera","0","flash","off","zoom",1,"cameras",new JSONArray().put(Wire.object("id","0","label","Rear","minFocusDiopters",10,"maxZoom",10,"flashModes",new JSONArray(List.of("off","auto","on","torch")),"photos",new JSONArray().put(Wire.object("key","3968x2976","width",3968,"height",2976,"ratio","4:3")))).put(Wire.object("id","1","label","Front")));}
 static MotionEvent rotary(float value){MotionEvent.PointerProperties p=new MotionEvent.PointerProperties();p.id=0;MotionEvent.PointerCoords c=new MotionEvent.PointerCoords();c.setAxisValue(MotionEvent.AXIS_SCROLL,value);return MotionEvent.obtain(0,1,MotionEvent.ACTION_SCROLL,1,new MotionEvent.PointerProperties[]{p},new MotionEvent.PointerCoords[]{c},0,0,1,1,0,0,InputDevice.SOURCE_ROTARY_ENCODER,0);}
 @Test public void rotaryScrollAndClockDoNotOverlap()throws Exception{CaptureSettingsUi.help(activity,true);Dialog d=ShadowDialog.getLatestDialog();RoundMenuFrame root=RoundMenuTest.frame(d);RoundMenuTest.layout(root,480);ScrollView scroll=(ScrollView)root.getChildAt(0);MotionEvent event=rotary(-2);assertTrue(root.dispatchGenericMotionEvent(event));event.recycle();assertTrue(scroll.getScrollY()>0);CurvedClock clock=(CurvedClock)root.getChildAt(1);assertEquals(0,clock.getAlpha(),0.001);RoundMenuTest.save(root,"help-scrolled");}
 @Test public void touchBezelScrollsWithoutAFrame()throws Exception{CaptureSettingsUi.help(activity,true);RoundMenuFrame root=RoundMenuTest.frame(ShadowDialog.getLatestDialog());RoundMenuTest.layout(root,480);ScrollView scroll=(ScrollView)root.getChildAt(0);for(int i=0;i<3;i++){double angle=i*.20;MotionEvent e=MotionEvent.obtain(0,i*20,i==0?MotionEvent.ACTION_DOWN:i==2?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE,(float)(240+225*Math.cos(angle)),(float)(240+225*Math.sin(angle)),0);root.dispatchTouchEvent(e);e.recycle();}assertTrue(scroll.getScrollY()>0);}
 @Test public void zoomUsesFineRotaryStepsAndKeepsItsParent(){AtomicReference<JSONObject> sent=new AtomicReference<>();Controls.settings(activity,state(),true,sent::set);Dialog parent=ShadowDialog.getLatestDialog();GallerySettingsTest.text(parent,"Zoom · 1.0×").performClick();Dialog slider=ShadowDialog.getLatestDialog();RoundMenuFrame root=RoundMenuTest.frame(slider);RoundMenuTest.layout(root,480);root.rotate(1);GallerySettingsTest.text(slider,"Apply").performClick();assertEquals(1.05,sent.get().optDouble("value"),.001);assertTrue(parent.isShowing());assertFalse(slider.isShowing());}
 @Test public void resolutionBackReturnsToAspectPicker(){Controls.settings(activity,state(),true,c->{});Dialog settings=ShadowDialog.getLatestDialog();GallerySettingsTest.text(settings,"Photo · size / aspect ratio").performClick();Dialog ratios=ShadowDialog.getLatestDialog();GallerySettingsTest.text(ratios,"4:3").performClick();Dialog sizes=ShadowDialog.getLatestDialog();sizes.onBackPressed();assertFalse(sizes.isShowing());assertTrue(ratios.isShowing());ratios.onBackPressed();assertTrue(settings.isShowing());}
 @Test public void confirmedSaveShowsSavedAndFailureDoesNot(){CaptureSettingsUi.settings(activity,Wire.object("background",true),true,(c,done)->done.accept(Wire.object("background",false)));Dialog d=ShadowDialog.getLatestDialog();GallerySettingsTest.text(d,"Background capture").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals("Saved",ShadowToast.getTextOfLatestToast());assertTrue(d.isShowing());ShadowToast.reset();CaptureSettingsUi.settings(activity,Wire.object("background",true),true,(c,done)->done.accept(null));GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"Background capture").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertNull(ShadowToast.getTextOfLatestToast());}
 @Test public void mainMenuRemainsUnderCameraSettings()throws Exception{try(var controller=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity watch=controller.get();((View)ReflectionHelpers.getField(watch,"more")).performClick();Dialog parent=ShadowDialog.getLatestDialog();GallerySettingsTest.text(parent,"Camera settings").performClick();Dialog child=ShadowDialog.getLatestDialog();child.onBackPressed();assertTrue(parent.isShowing());assertFalse(child.isShowing());}}
 @Test public void quickIconsOpenCorrespondingSettingsAndPreviewHasOneStatus()throws Exception{try(var controller=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity watch=controller.get();ReflectionHelpers.setField(watch,"state",state());ReflectionHelpers.setField(watch,"connected",true);ReflectionHelpers.callInstanceMethod(watch,"render");for(String key:new String[]{"flashButton","timerButton","flipButton"}){assertTrue(((View)ReflectionHelpers.getField(watch,key)).performLongClick());Dialog d=ShadowDialog.getLatestDialog();assertTrue(d.isShowing());d.dismiss();}PreviewView preview=ReflectionHelpers.getField(watch,"preview");assertEquals("",ReflectionHelpers.getField(preview,"empty"));}}
 @Test public void quickSettingsSendOnlyTheirSetting(){AtomicReference<JSONObject> command=new AtomicReference<>();Controls.flashSettings(activity,state(),true,command::set);GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"Torch").performClick();assertEquals("flash",command.get().optString("op"));assertEquals("torch",command.get().optString("value"));Controls.cameraSettings(activity,state(),true,command::set);GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"Front").performClick();assertEquals("1",command.get().optString("value"));}
}
